-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.set_flag(card jsonb, flag integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not public.is_allowed_user() then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  if flag not between 0 and 7 then
    raise exception 'invalid_flag' using errcode = '22023';
  end if;
  perform public.lock_user_study();
  perform public.change_card(gen_random_uuid(), 'flag', card, now(), jsonb_build_object('flag', flag));
end;
$function$;

grant execute on function public.set_flag(card jsonb, flag integer) to authenticated;
grant execute on function public.set_flag(card jsonb, flag integer) to service_role;
